import{_ as p,a0 as i,w as m,s as u,ao as n,I as l,x as o,a1 as e,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"保護家庭網絡三部曲 | LCTT x X-CMD","titleTemplate":false,"description":"保護家庭網絡三部曲 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"保護家庭網絡三部曲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"保護家庭網絡三部曲 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220914 3 steps to protect your home network","title":"保護家庭網絡三部曲","tag":"202210","desc":""},"relativePath":"202210/20220914 3 steps to protect your home network.md","filePath":"[post].md"}'),d={name:"202210/20220914 3 steps to protect your home network.md"};function a(f,t,T,w,k,g){const r=i("Link");return m(),u("div",null,[t[46]||(t[46]=n('<h1 id="保護家庭網絡三部曲" tabindex="-1">保護家庭網絡三部曲 <a class="header-anchor" href="#保護家庭網絡三部曲" aria-label="Permalink to “保護家庭網絡三部曲”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/01/183650wcrjnshjn9cwzqws.jpg" alt=""></p><blockquote><p>都有誰可以訪問你的家庭網絡？隨着物聯網（IoT）的普及，有時在運行在你家庭網絡上的服務比你想像的更多。我們應當設法保護它免受不需要的訪問。</p></blockquote><p>今天，互聯網連接的典型結構是家裏有一個<strong>路由器</strong>，通常是一個位於你家某個地方的小盒子，它充當了通往互聯網世界的網關。路由器創建了一個本地網絡，你將你的設備連接到這個本地網絡，包括你的電腦、手機、電視、遊戲機，以及其他任何需要連接到互聯網或相互連接的設備。我們很容易將路由器當作一個分界線，一邊是互聯網而另一邊是你的設備。但這是一個可怕的誤解，因為在現實中，你的路由器的一邊是整個<em>計算機網絡世界</em>，另一邊是你的數字生活。當你直接使用互聯網時，你是在訪問別人的計算機網絡的共享區域。當你不使用互聯網時，它卻並沒有消失，有很多腳本和程序被設計用以訪問數以百萬計的路由器，試圖找到開放的端口或服務。隨着物聯網（IoT）的普及，有時在運行在你家庭網絡上的服務比你想像的更多。通過以下三個步驟，你可以審計並保護你的家庭網絡免受不必要的訪問和攻擊。</p><h3 id="_1、協議先行" tabindex="-1">1、協議先行 <a class="header-anchor" href="#_1、協議先行" aria-label="Permalink to “1、協議先行”">​</a></h3><p>路由器的部分工作是將互聯網與你的家庭網絡分開。但當你訪問互聯網時，你邀請互聯網的某些部分進入你的家庭。這意味着你創建了一個例外規則，繞過了阻止互聯網進入你的本地網絡的一般規則。</p><p>在許多網站上，通過你的路由器的僅是文本內容。例如，當你訪問你最喜歡的Blog網站，閲讀最新的科技新聞時，你下載了幾頁文字。你閲讀文本，然後繼續訪問。這是一個簡單的一對一的連接。</p>',7)),l("p",null,[t[2]||(t[2]=o("然而，HTTPS 協議是強大的，在互聯網上運行的應用程序也充滿了多樣性。例如，當你訪問某個網站時，你不只是在下載文本。你會得到圖形，也許還有腳本或電子書。你還在後台下載 cookie，這有助於網站管理員瞭解誰在訪問網站、加強對移動設備的支持、為更好的可訪問性提供新設計並瞭解讀者喜歡的內容。當你網上衝浪時，你可能不會想到 cookie 或流量分析是與你交互的東西，它是被“藏入”頁面交互的東西，因為 HTTPS 協議的設計是廣泛而通用的，在多數場景被高度信任。當你通過 HTTPS（或者説，在一個瀏覽器中）訪問一個網站時，你可能在不知情的情況下默認同意自動下載文件，但你認為這些文件是有用的和無關緊要的。對於一種旨在減少信任的文件共享模式，你可以嘗試一下 ",-1)),e(r,{href:"https://opensource.com/article/20/10/gemini-internet-protocol"},{default:s(()=>[...t[0]||(t[0]=[o("Gemini",-1)])]),_:1}),t[3]||(t[3]=o(" 或 ",-1)),e(r,{href:"https://opensource.com/article/16/12/yearbook-compute-its-1989#gopher"},{default:s(()=>[...t[1]||(t[1]=[o("Gopher",-1)])]),_:1}),t[4]||(t[4]=o(" 協議。",-1))]),t[47]||(t[47]=l("p",null,"當你加入一個視頻會議時，你也使用了類似的協議。你不僅要下載頁面上的文字、用於流量監控的cookie，還要下載視頻和音頻材料。",-1)),t[48]||(t[48]=l("p",null,"有些網站的設計甚至更進一步，它們被設計成允許用户分享其電腦屏幕，有時甚至是對他們電腦的控制。這樣設計的初衷是有助於遠程技術人員修復電腦上的問題，但在現實中，用户可能被欺騙訪問這一網站，導致財務憑證和個人數據被盜。",-1)),l("p",null,[t[6]||(t[6]=o("如果一個提供文字文章的網站要求你允許它在你閲讀時調用網絡攝像頭，你理應高度警惕。當一個設備需要訪問互聯網時，你也應當保持同樣的謹慎和警惕。當你把一個設備連接到網絡時，重要的是要關注你同意了何種隱性協議。一個旨在控制你房子裏的照明的設備不應該",-1)),t[7]||(t[7]=l("em",null,"要求",-1)),t[8]||(t[8]=o("互聯網接入，但事實上許多設備需要並且沒有明確説明你授予該設備什麼權限。許多物聯網設備都",-1)),t[9]||(t[9]=l("em",null,"希望",-1)),t[10]||(t[10]=o("接入互聯網，這樣你就可以在離家時通過互聯網訪問該設備。這也是“智慧家庭”的部分吸引力。然而，我們不可能知道所有設備運行的是什麼代碼。在可能的情況下，使用開源和值得信賴的軟件，如 ",-1)),e(r,{href:"https://opensource.com/article/20/12/home-assistant"},{default:s(()=>[...t[5]||(t[5]=[o("Home Assistant",-1)])]),_:1}),t[11]||(t[11]=o(" 來與你的物聯網設備對接。",-1))]),t[49]||(t[49]=n('<h3 id="_2、創建訪客網絡" tabindex="-1">2、創建訪客網絡 <a class="header-anchor" href="#_2、創建訪客網絡" aria-label="Permalink to “2、創建訪客網絡”">​</a></h3><p>許多現代路由器可以為你的家庭創建第二個網絡（通常在配置面板中稱為 “訪客網絡”）。你可能覺得你不需要訪客網絡，但實際上，訪客網絡是十分有意義的。它旨在為訪問你房子的人提供互聯網訪問，而你不需要告訴他們你的私人網絡密碼。例如在我家的門廳裏，我有一個牌子標明瞭訪客網絡的名稱和密碼。任何來訪的人都可以加入該網絡以訪問互聯網。</p><p>另一方面可以用於物聯網、邊緣設備和家庭實驗室的應用。當我去年購買 “可編程” 的聖誕燈時，我驚訝地發現，為了連接這些燈，它們必須連接到互聯網。當然，這些來自無名工廠的 50 美元的燈沒有附帶源代碼，也沒有任何方法可以與嵌入在適配器中的固件進行交互或檢查，所以我對我同意將它們連接到我的本地網絡有一定的顧慮。它們已經被永久地歸入了我的訪客網絡。</p><p>每個路由器供應商都是不同的，所以沒有關於如何在你的路由器上創建一個 “沙盒” 訪客網絡的通用指令。一般來説，你通過一個網絡瀏覽器訪問你的家庭路由器。你的路由器的地址有時印在路由器的底部，它以 192.168 或 10 開頭。</p><p>訪問路由器地址，用你配置互聯網服務時使用的憑證登錄。這通常是簡單的 “admin” 和一個數字密碼（有時，這個密碼也印在路由器上）。如果你不知道登錄方式，請致電給你的互聯網供應商或者製造商諮詢。</p><p>在圖形界面中，找到 “訪客網絡” 的面板。這個選項在我的路由器的<strong>高級</strong>配置中，但它可能在你的路由器的其他地方，它甚至可能不叫 “訪客網絡”（或者它甚至可能不是一個選項）。具體情況因廠商而異。</p><p><img src="https://opensource.com/sites/default/files/2022-08/router-guest-network.jpg" alt="創建訪客網絡"></p><p>這可能需要耐心的尋找。如果你發現你的設備有這個選擇，那麼你可以為訪客建立一個訪客網絡，包括在不受信任的燈泡上運行的應用程序。</p><h3 id="_3、配置防火牆" tabindex="-1">3、配置防火牆 <a class="header-anchor" href="#_3、配置防火牆" aria-label="Permalink to “3、配置防火牆”">​</a></h3><p>你的路由器可能已經存在一個默認運行的防火牆。防火牆將不需要的流量擋在你的網絡之外，通常是將傳入的數據包限制在 HTTP 和 HTTPS（瀏覽器流量）以及其他一些常用的協議上，並拒絕不是你發起的請求。你可以通過登錄你的路由器並尋找 “防火牆” 或 “安全” 設置來檢查防火牆是否正在運行。</p><p>然而，許多設備可以運行它們自己的防火牆。網絡之所以被稱為<em>網絡</em>是因為在網絡上的設備互相能進行連接。在設備之間設置防火牆，就像在你的房子裏鎖上一扇門。客人可以在大廳裏遊蕩，但如果沒有合適的鑰匙，他們就不會被邀請進入你的私人辦公室。</p>',11)),l("p",null,[t[14]||(t[14]=o("在 Linux 上，你可以使用 ",-1)),e(r,{href:"https://opensource.com/article/19/7/make-linux-stronger-firewalls"},{default:s(()=>[...t[12]||(t[12]=[o("firewalld",-1)])]),_:1}),t[15]||(t[15]=o(" 接口和 ",-1)),e(r,{href:"https://www.redhat.com/sysadmin/secure-linux-network-firewall-cmd"},{default:s(()=>[...t[13]||(t[13]=[o("firewall-cmd",-1)])]),_:1}),t[16]||(t[16]=o(" 命令來配置你的防火牆。在其他操作系統上，防火牆有時在一個標有 “安全” 或 “共享” 的控制面板中（有時兩者都有）。 大多數默認的防火牆設置只允許出站流量（即你通過打開瀏覽器並導航到一個網站而啓動的流量）和響應你的請求的入站流量（即響應你的導航的網絡數據）。不是由你發起的傳入流量會被阻止。",-1))]),l("p",null,[t[20]||(t[20]=o("你可以根據需要配置相關規則以允許特定的流量，例如 ",-1)),e(r,{href:"https://www.redhat.com/sysadmin/access-remote-systems-ssh"},{default:s(()=>[...t[17]||(t[17]=[o("SSH 連接",-1)])]),_:1}),t[21]||(t[21]=o("、",-1)),e(r,{href:"https://www.redhat.com/sysadmin/accessing-remote-desktops"},{default:s(()=>[...t[18]||(t[18]=[o("VNC 連接",-1)])]),_:1}),t[22]||(t[22]=o("，或 ",-1)),e(r,{href:"https://opensource.com/article/18/5/maptool"},{default:s(()=>[...t[19]||(t[19]=[o("遊戲服務器",-1)])]),_:1}),t[23]||(t[23]=o(" 主機。",-1))]),t[50]||(t[50]=l("h3",{id:"監控你的網絡",tabindex:"-1"},[o("監控你的網絡 "),l("a",{class:"header-anchor",href:"#監控你的網絡","aria-label":"Permalink to “監控你的網絡”"},"​")],-1)),l("p",null,[t[27]||(t[27]=o("這些技巧有助於建立起你對周圍發生的事情的認識。下一步是 ",-1)),e(r,{href:"https://opensource.com/article/19/2/network-monitoring-tools"},{default:s(()=>[...t[24]||(t[24]=[o("監控你的網絡",-1)])]),_:1}),t[28]||(t[28]=o("。你可以從簡單的開始，例如在你的訪客網絡的測試服務器上運行 ",-1)),e(r,{href:"https://www.redhat.com/sysadmin/protect-systems-fail2ban"},{default:s(()=>[...t[25]||(t[25]=[o("Fail2ban",-1)])]),_:1}),t[29]||(t[29]=o("。看一下日誌，如果你的路由器提供日誌的話。你不必對 TCP/IP 和數據包以及其他進階知識瞭如指掌，就可以看到互聯網是一個繁忙而嘈雜的地方，當你在家裏安裝一個新設備時，無論是物聯網、移動設備、台式機或筆記本電腦、遊戲機，甚至是 ",-1)),e(r,{href:"https://opensource.com/article/22/3/raspberry-pi-projects-2022"},{default:s(()=>[...t[26]||(t[26]=[o("樹莓派",-1)])]),_:1}),t[30]||(t[30]=o("，而親身體會到這一點對你採取預防措施有很大啓發。",-1))]),t[51]||(t[51]=l("hr",null,null,-1)),l("p",null,[t[32]||(t[32]=o("via: ",-1)),e(r,{href:"https://opensource.com/article/22/9/protect-home-network"},{default:s(()=>[...t[31]||(t[31]=[o("https://opensource.com/article/22/9/protect-home-network",-1)])]),_:1})]),l("p",null,[t[37]||(t[37]=o("作者：",-1)),e(r,{href:"https://opensource.com/users/seth"},{default:s(()=>[...t[33]||(t[33]=[o("Seth Kenlon",-1)])]),_:1}),t[38]||(t[38]=o(" 選題：",-1)),e(r,{href:"https://github.com/lkxed"},{default:s(()=>[...t[34]||(t[34]=[o("lkxed",-1)])]),_:1}),t[39]||(t[39]=o(" 譯者：",-1)),e(r,{href:"https://github.com/PeterPan0106"},{default:s(()=>[...t[35]||(t[35]=[o("PeterPan0106",-1)])]),_:1}),t[40]||(t[40]=o(" 校對：",-1)),e(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[36]||(t[36]=[o("wxy",-1)])]),_:1})]),l("p",null,[t[43]||(t[43]=o("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[41]||(t[41]=[o("LCTT",-1)])]),_:1}),t[44]||(t[44]=o(" 原創編譯，",-1)),e(r,{href:"https://linux.cn/"},{default:s(()=>[...t[42]||(t[42]=[o("Linux中國",-1)])]),_:1}),t[45]||(t[45]=o(" 榮譽推出",-1))])])}const C=p(d,[["render",a]]);export{b as __pageData,C as default};
